"""``docs/architecture/function-map.md``: one Mermaid flowchart per prototype area, prototype on the left."""

from __future__ import annotations

import json
import re
from collections import Counter

from .entries import STATUSES, Entry, ReferenceMap

GENERATED_NOTICE = (
    "Generated by tools/map (`just reference-map --write`) from reference-map.yaml. Do not edit."
)
AREA_TITLES = {"agents-and-harness": "agents and harness", "examples": "examples"}
_PACKAGE_SOURCE = re.compile(r"^packages/([^/]+)/src/[^/]+/(.*)$")
_CLASSES = (
    "classDef ported fill:#d8f3dc,stroke:#2d6a4f",
    "classDef partial fill:#f1faf3,stroke:#2d6a4f,stroke-width:2px,stroke-dasharray: 6 3",
    "classDef inprogress fill:#fff3bf,stroke:#b08900",
    "classDef planned fill:#e7f0fa,stroke:#3a6ea5",
    "classDef dropped fill:#eeeeee,stroke:#888888,stroke-dasharray: 4 3,color:#666666",
    "classDef home fill:#ffffff,stroke:#3a6ea5",
)


def render_function_map(reference: ReferenceMap) -> str:
    lines = ["# Function map: prototype to benchhand-next", "", GENERATED_NOTICE, ""]
    lines += [
        f"Each diagram follows one area of the prototype at `{reference.reference_commit[:7]}`. "
        "A prototype file is on the left and its home in benchhand-next is on the right. "
        "The arrow names the phase that builds the home: `P1` is Phase 1 of the design plan. "
        "`phase open` means the home waits on an open question.",
        "",
        "- Green: ported.",
        "- Pale green with a dashed green border: partial. Part of the file is ported; the list below says "
        "what is left and which phase owns it.",
        "- Amber: in progress.",
        "- Blue: planned.",
        "- Gray and dashed: dropped. The box it points to gives the reason.",
        "",
        *_totals(reference),
        *_partial_notes(reference),
    ]
    for area in _areas(reference):
        entries = [entry for entry in reference.entries if entry.area == area]
        lines += [
            f"## {AREA_TITLES.get(area, area)}",
            "",
            "```mermaid",
            *_flowchart(area, entries),
            "```",
            "",
        ]
    return "\n".join(lines).rstrip("\n") + "\n"


def status_counts(reference: ReferenceMap) -> Counter[str]:
    return Counter(entry.status for entry in reference.entries)


def _areas(reference: ReferenceMap) -> list[str]:
    return sorted({entry.area for entry in reference.entries}, key=lambda area: (area in AREA_TITLES, area))


def _totals(reference: ReferenceMap) -> list[str]:
    lines = ["| Area | Entries | " + " | ".join(STATUSES) + " |", "|---|---|" + "---|" * len(STATUSES)]
    for area in _areas(reference):
        counts = Counter(entry.status for entry in reference.entries if entry.area == area)
        cells = " | ".join(str(counts[status]) for status in STATUSES)
        lines.append(f"| {AREA_TITLES.get(area, area)} | {sum(counts.values())} | {cells} |")
    total = status_counts(reference)
    cells = " | ".join(str(total[status]) for status in STATUSES)
    return [*lines, f"| **all** | **{len(reference.entries)}** | {cells} |", ""]


def _partial_notes(reference: ReferenceMap) -> list[str]:
    """What each partial entry leaves out, and the open question each entry without a phase waits on."""
    lines: list[str] = []
    for title, entries in (
        ("Partly ported:", [entry for entry in reference.entries if entry.status == "partial"]),
        ("Phase open:", [entry for entry in reference.entries if entry.homes and entry.phase is None]),
    ):
        if entries:
            lines += [title, "", *(f"- `{entry.path}`: {entry.note}" for entry in entries), ""]
    return lines


def _label(text: str) -> str:
    return json.dumps(text.replace('"', "'"), ensure_ascii=False)


def _short_home(home: str) -> str:
    """``packages/benchhand-core/src/benchhand_core/record/x.py`` as ``benchhand-core/record/x.py``."""
    found = _PACKAGE_SOURCE.match(home)
    return f"{found.group(1)}/{found.group(2)}" if found else home


def _short_path(path: str, area: str) -> str:
    return path.removeprefix(f"skills/{area}/")


def _flowchart(area: str, entries: list[Entry]) -> list[str]:
    left: list[str] = []
    right: dict[str, str] = {}
    edges: list[str] = []
    classes: list[str] = []
    for index, entry in enumerate(entries):
        node = f"p{index}"
        left.append(f"        {node}[{_label(_short_path(entry.path, area))}]")
        classes.append(f"    class {node} {entry.status.replace('-', '')}")
        for target, edge in _targets(entry):
            if target not in right:
                right[target] = f"h{len(right)}"
            edges.append(f"    {node} {edge} {right[target]}")
    lines = [
        "flowchart LR",
        f"    subgraph prototype[{_label('prototype: ' + _subtitle(area))}]",
        *left,
        "    end",
    ]
    lines += ['    subgraph next["benchhand-next"]']
    for target, node in right.items():
        lines.append(f"        {node}[{_label(target)}]")
    lines += ["    end", *edges, *classes]
    lines += [
        f"    class {node} {'dropped' if target.startswith('dropped: ') else 'home'}"
        for target, node in right.items()
    ]
    return [*lines, *(f"    {definition}" for definition in _CLASSES)]


def _subtitle(area: str) -> str:
    return "skills/" + area if area not in AREA_TITLES else AREA_TITLES[area]


def _targets(entry: Entry) -> list[tuple[str, str]]:
    """The right-hand nodes of an entry, each with the arrow to it."""
    if entry.status == "dropped":
        return [(f"dropped: {entry.reason}", "-. dropped .->")]
    arrow = '-->|"phase open"|' if entry.phase is None else f'-->|"P{entry.phase}"|'
    return [(_short_home(home), arrow) for home in entry.homes]
